// Two Sum using Hash Map
var table = AnimatedHashTable<Int, Int>()
let nums = [3, 2, 4]
let target = 6

func twoSumHash(_ nums: [Int], _ target: Int, t: inout AnimatedHashTable<Int, Int>) -> [Int] {
    for i in 0..<nums.count {
        let val = nums[i]
        let complement = target - val
        if let compIndex = t.get(complement) {
            return [compIndex, i]
        }
        t.put(val, i)
    }
    return []
}

let indices = twoSumHash(nums, target, t: &table)
